package com.jjm.oficina.controller;
import com.jjm.oficina.config.AutenticacionTokenFilter;
import com.jjm.oficina.modelo.*;
import com.jjm.oficina.repositorio.*;
import com.jjm.oficina.servicio.*;
import org.junit.jupiter.api.*;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class CanalProyectoTest {
    final JdbcTemplate jdbc=mock(JdbcTemplate.class);final UsuarioRepository usuarios=mock(UsuarioRepository.class);final ProyectoRepository proyectos=mock(ProyectoRepository.class);final MiembroEquipoRepository miembros=mock(MiembroEquipoRepository.class);final MiembroProyectoRepository asignaciones=mock(MiembroProyectoRepository.class);final PermisosService permisos=mock(PermisosService.class);final ReportesDiariosService diarios=mock(ReportesDiariosService.class);final SesionService sesiones=mock(SesionService.class);
    Usuario u;MockMvc mvc;
    private final com.jjm.oficina.servicio.AsistenciaAutomaticaService asistencia=mock(com.jjm.oficina.servicio.AsistenciaAutomaticaService.class);
    @BeforeEach void preparar(){when(asistencia.habilitacionReporte(anyInt(),any())).thenReturn(Map.of("habilitado",true));u=new Usuario();u.setId(7);u.setEstado("Activo");Rol rol=new Rol();rol.setNombre("Colaborador");u.setRol(rol);when(usuarios.findById(7)).thenReturn(Optional.of(u));when(proyectos.existsById(2)).thenReturn(true);MiembroEquipo m=new MiembroEquipo();m.setId(42);m.setUsuario(u);when(miembros.findByUsuarioId(7)).thenReturn(Optional.of(m));when(asignaciones.existsByIdProyectoAndIdMiembro(2,42)).thenReturn(true);when(sesiones.obtenerUsuario("prueba")).thenReturn(7);when(diarios.inicio()).thenReturn("2026-10-13");mvc=MockMvcBuilders.standaloneSetup(new CanalProyectoController(jdbc,usuarios,proyectos,miembros,asignaciones,permisos,diarios,asistencia)).addFilters(new AutenticacionTokenFilter(sesiones,new ObjectMapper())).build();}
    @Test void identidadDelTokenNoSeSustituyePorHeader()throws Exception{mvc.perform(get("/api/canales/proyectos/2").header("Authorization","Bearer prueba").header("X-Usuario-Id","99")).andExpect(status().isOk()).andExpect(jsonPath("$.puedeGestionar").value(false));verify(usuarios,never()).findById(99);mvc.perform(get("/api/canales/proyectos/2").header("X-Usuario-Id","7")).andExpect(status().isUnauthorized());}
    @Test void ajenoOEmpresaNoVeArchivos()throws Exception{when(asignaciones.existsByIdProyectoAndIdMiembro(2,42)).thenReturn(false);mvc.perform(get("/api/canales/proyectos/2/archivos").header("Authorization","Bearer prueba")).andExpect(status().isForbidden());u.getRol().setNombre("Empresa");mvc.perform(get("/api/canales/proyectos/2").header("Authorization","Bearer prueba")).andExpect(status().isForbidden());verifyNoInteractions(jdbc);}
    @Test void directivoAsignadoConsultaPeroNoSubeNiMarcaDias()throws Exception{u.getRol().setNombre("Directivo escolar");mvc.perform(get("/api/canales/proyectos/2").header("Authorization","Bearer prueba")).andExpect(jsonPath("$.puedeConsultarTodos").value(true)).andExpect(jsonPath("$.puedeSubir").value(false));mvc.perform(post("/api/canales/proyectos/2/archivos").header("Authorization","Bearer prueba").contentType(MediaType.APPLICATION_JSON).content("{\"nombre\":\"a.pdf\",\"carpeta\":\"Proyecto\",\"base64\":\"JVBERi0=\"}")).andExpect(status().isForbidden());mvc.perform(put("/api/canales/proyectos/2/calendario").header("Authorization","Bearer prueba").contentType(MediaType.APPLICATION_JSON).content("{\"fecha\":\"2026-10-13\",\"laboral\":false}")).andExpect(status().isForbidden());verifyNoInteractions(jdbc);}
    @Test void calendarioNoModificaHorasNiAsistencia()throws Exception{when(permisos.esSuperadministrador(u)).thenReturn(true);mvc.perform(put("/api/canales/proyectos/2/calendario").header("Authorization","Bearer prueba").contentType(MediaType.APPLICATION_JSON).content("{\"fecha\":\"2026-10-13\",\"laboral\":false,\"motivo\":\"Descanso\"}")).andExpect(status().isOk());verify(jdbc).update(contains("INSERT INTO pmo_calendario_proyecto"),any(Object[].class));verifyNoMoreInteractions(jdbc);verifyNoInteractions(diarios);}
    @Test void descargaRestringeArchivoAlProyectoYLoEntregaComoAdjunto()throws Exception{when(jdbc.queryForList(contains("SELECT nombre,mime,contenido"),eq(9L),eq(2))).thenReturn(List.of(Map.of("nombre","evidencia.pdf","mime","application/pdf","contenido","%PDF-datos".getBytes())));mvc.perform(get("/api/canales/proyectos/2/archivos/9").header("Authorization","Bearer prueba")).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(content().contentType(MediaType.APPLICATION_OCTET_STREAM));verify(jdbc).queryForList(contains("id_proyecto=? AND eliminado=FALSE"),eq(9L),eq(2));}
    @Test void retirarArchivoAjenoNoLoBorra()throws Exception{mvc.perform(delete("/api/canales/proyectos/2/archivos/9").header("Authorization","Bearer prueba")).andExpect(status().isNotFound());verify(jdbc).update(contains("id_usuario=?"),eq(9L),eq(2),eq(7));}
    @Test void reporteNoPermiteElegirOtroUsuario()throws Exception{when(diarios.guardar(eq(2),eq(7),any())).thenReturn(Map.of("estado","correcto"));mvc.perform(post("/api/canales/proyectos/2/reportes-diarios").header("Authorization","Bearer prueba").header("X-Usuario-Id","99").contentType(MediaType.APPLICATION_JSON).content("{\"fecha\":\"2026-10-13\",\"actividad\":\"Desarrollé el entregable\",\"resultado\":\"Prueba completa\",\"fase\":\"Ejecución\",\"horas\":3,\"evidencia\":\"https://example.org\"}")).andExpect(status().isOk());verify(diarios).guardar(eq(2),eq(7),any());}
    @Test void historialAjenoSeRechazaYRevisionNecesitaAdmin()throws Exception{when(jdbc.queryForList(contains("SELECT id_usuario"),eq(9L),eq(2))).thenReturn(List.of(Map.of("id_usuario",8)));mvc.perform(get("/api/canales/proyectos/2/reportes-diarios/9/historial").header("Authorization","Bearer prueba")).andExpect(status().isForbidden());mvc.perform(put("/api/canales/proyectos/2/reportes-diarios/9").header("Authorization","Bearer prueba").contentType(MediaType.APPLICATION_JSON).content("{\"estado\":\"Aprobado\"}")).andExpect(status().isForbidden());verifyNoInteractions(diarios);}
    @Test void rechazaExtensionEjecutableYPdfDisfrazado()throws Exception{for(String nombre:List.of("evidencia.exe","evidencia.pdf"))mvc.perform(post("/api/canales/proyectos/2/archivos").header("Authorization","Bearer prueba").contentType(MediaType.APPLICATION_JSON).content("{\"nombre\":\""+nombre+"\",\"carpeta\":\"Proyecto\",\"base64\":\"aG9sYQ==\"}")).andExpect(status().isBadRequest());verify(jdbc,never()).update(anyString(),any(Object[].class));}
    @Test void formularioNoPuedeEntregarseAntesDe16ConPeticionDirecta()throws Exception{when(asistencia.habilitacionReporte(anyInt(),any())).thenReturn(Map.of("habilitado",false,"mensaje","El reporte se habilita a las 16:00."));mvc.perform(post("/api/canales/proyectos/2/reportes-diarios").header("Authorization","Bearer prueba").contentType(MediaType.APPLICATION_JSON).content("{\"fecha\":\"2026-10-14\",\"actividad\":\"Actividad suficiente\",\"resultado\":\"Resultado suficiente\",\"fase\":\"Diseño\",\"horas\":10,\"evidencia\":\"https://example.org\"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.mensaje").value("El reporte se habilita a las 16:00."));verifyNoInteractions(diarios);}
    @Test void consultaDeHabilitacionUsaCuentaDelTokenYRechazaFechaInvalida()throws Exception{mvc.perform(get("/api/canales/proyectos/2/habilitacion-reporte?fecha=2026-10-14").header("Authorization","Bearer prueba").header("X-Usuario-Id","99")).andExpect(status().isOk());verify(asistencia).habilitacionReporte(eq(7),eq(java.time.LocalDate.of(2026,10,14)));mvc.perform(get("/api/canales/proyectos/2/habilitacion-reporte?fecha=invalida").header("Authorization","Bearer prueba")).andExpect(status().isBadRequest());}
}
